#include <iostream>
#include <string>

struct ScreenMode {
    std::string name;
    int width;
    int height;
    int colors;
};

bool is_valid_pixel(const ScreenMode& mode, int x, int y) {
    return (x >= 0 && x < mode.width && y >= 0 && y < mode.height);
}

int main() {
    ScreenMode vgaHi{"VGAHI", 640, 480, 16};

    std::cout << "Che do: " << vgaHi.name << "\n";
    std::cout << "Do phan giai: " << vgaHi.width << "x" << vgaHi.height << "\n";
    std::cout << "Goc tren-trai: (0,0)\n";
    std::cout << "Goc duoi-phai: (" << (vgaHi.width - 1) << "," << (vgaHi.height - 1) << ")\n";

    int test_x = 150;
    int test_y = 200;
    std::cout << "Diem (" << test_x << "," << test_y << "): " 
              << (is_valid_pixel(vgaHi, test_x, test_y) ? "Hop le" : "Ngoai man hinh") << "\n";

    int oob_x = 640;
    int oob_y = 480;
    std::cout << "Diem (" << oob_x << "," << oob_y << "): " 
              << (is_valid_pixel(vgaHi, oob_x, oob_y) ? "Hop le" : "Ngoai man hinh") << "\n";

    return 0;
}

#include <iostream>
#include <string>

// Mo phong co che quan ly do hoa BGI theo chuan C++17
enum GraphicsError {
    grOk = 0,
    grNoInitGraph = -1,
    grNotDetected = -2,
    grFileNotFound = -3
};

std::string grapherrormsg(int code) {
    switch (code) {
        case grOk: return "No error";
        case grNoInitGraph: return "(BGI) Khong co BGI";
        case grNotDetected: return "Graphics hardware not detected";
        case grFileNotFound: return "Device driver file not found";
        default: return "Unknown graphics error";
    }
}

struct GraphicsContext {
    int driver = 0; // DETECT = 0
    int mode = 0;
    int maxX = 0;
    int maxY = 0;
    int maxColor = 0;
    bool initialized = false;
};

GraphicsError initgraph_sim(GraphicsContext& ctx, int reqDriver, const std::string& path) {
    if (path.empty() || path == "INVALID_PATH") {
        return grFileNotFound;
    }
    if (reqDriver == 0) { // DETECT -> VGAHI (640x480, 16 mau)
        ctx.driver = 9;   // VGA
        ctx.mode = 2;     // VGAHI
        ctx.maxX = 639;
        ctx.maxY = 479;
        ctx.maxColor = 15; // 16 mau: 0..15
        ctx.initialized = true;
        return grOk;
    }
    return grNotDetected;
}

void closegraph_sim(GraphicsContext& ctx) {
    ctx.initialized = false;
    std::cout << "Da giai phong che do do hoa, tro ve che do van ban.\n";
}

int main() {
    GraphicsContext ctx;
    int gd = 0; // DETECT

    std::cout << "--- Kiem thu 1: Thu muc driver sai ---\n";
    GraphicsError err1 = initgraph_sim(ctx, gd, "INVALID_PATH");
    if (err1 != grOk) {
        std::cout << "Loi: " << grapherrormsg(err1) << " (Ma: " << err1 << ")\n";
    }

    std::cout << "--- Kiem thu 2: Khoi tao thanh cong ---\n";
    GraphicsError err2 = initgraph_sim(ctx, gd, "C:\\BC\\BGI");
    if (err2 == grOk) {
        std::cout << "Che do man hinh = " << ctx.driver << "\n";
        std::cout << "Mode man hinh = " << ctx.mode << "\n";
        std::cout << "Do phan giai: " << ctx.maxX << "," << ctx.maxY << "\n";
        std::cout << "So mau ho tro: " << (ctx.maxColor + 1) << " (getmaxcolor: " << ctx.maxColor << ")\n";
        closegraph_sim(ctx);
    }

    return 0;
}
